'use strict';
const siteNavPaths={all:'M4 5h16v14H4z M8 9h8 M8 13h6',favorite:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z',draft:'M5 4h10l4 4v12H5z M14 4v5h5 M8 13h8 M8 16h5',solo:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z M5 21v-2a7 7 0 0 1 14 0v2',combo:'M8 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z M17 12a3 3 0 1 0 0-6 M2 20v-2a6 6 0 0 1 12 0v2 M17 15a5 5 0 0 1 5 5',relations:'M9 8 7 6a4 4 0 0 0-6 5l5 5a4 4 0 0 0 6 0l2-2 M15 16l2 2a4 4 0 0 0 6-5l-5-5a4 4 0 0 0-6 0l-2 2 M8 12l8 0',graph:'M12 5 5 18h14L12 5Z M12 2v6 M2 18h6 M16 18h6',gallery:'M3 4h18v16H3z M3 16l5-5 5 5 3-3 5 5 M16 8h.01'};
function siteLineIcon(path){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.setAttribute('class','siteNavIcon');svg.innerHTML='<path d="'+path+'" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>';return svg}
function polishSiteShell(){document.body.classList.add('sitePolish');document.body.dataset.page=view.type;const header=document.querySelector('header');header.classList.add('siteHeader');header.querySelector(':scope > .row')?.classList.add('siteHeaderActions');const brand=header.firstElementChild;brand.classList.add('siteBrand');if(!brand.querySelector('.siteBrandMark')){const mark=document.createElement('span');mark.className='siteBrandMark';mark.setAttribute('aria-hidden','true');mark.append(siteLineIcon('M12 2 14.5 9.5 22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z M19 3v4 M17 5h4'));brand.prepend(mark)}
 const aside=document.querySelector('aside');let content=$('siteSidebarContent');if(!content){content=document.createElement('div');content.id='siteSidebarContent';while(aside.firstChild)content.append(aside.firstChild);aside.append(content);const toggle=document.createElement('button');toggle.id='siteMobileNavigation';toggle.type='button';toggle.setAttribute('aria-controls',content.id);toggle.setAttribute('aria-expanded','false');toggle.innerHTML='<span>导航与档案</span><strong id="siteMobileCurrent"></strong><span class="siteNavChevron" aria-hidden="true">⌄</span>';toggle.onclick=()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));aside.classList.toggle('siteMobileOpen',open)};aside.prepend(toggle)}
 const labels={all:'全部帖子',favorite:'我的收藏',draft:'草稿箱',solo:'角色贴膜站',combo:'家产小屋',relations:'关系档案',graph:'角色关系图',gallery:'拾星馆'};$('siteMobileCurrent').textContent=view.type==='game'?game(view.id)?.name||'档案':view.type==='character'?character(view.id)?.name||'角色':labels[view.type]||'全部帖子';
 const counts={all:data.posts.filter(p=>p.status==='published').length,favorite:data.posts.filter(p=>p.favorite&&p.status==='published').length};document.querySelectorAll('#nav button[data-view]').forEach(b=>{if(b.dataset.siteStyled)return;b.dataset.siteStyled='true';const type=b.dataset.view;b.setAttribute('aria-label',b.textContent.trim());if(siteNavPaths[type])b.prepend(siteLineIcon(siteNavPaths[type]));if(counts[type]!==undefined){const n=document.createElement('span');n.className='siteNavCount';n.textContent=counts[type];n.setAttribute('aria-hidden','true');b.append(n)}if(b.classList.contains('active'))b.setAttribute('aria-current','page')});
 document.querySelectorAll('#games button[data-view]').forEach(b=>{if(b.classList.contains('active'))b.setAttribute('aria-current','page')});polishSiteFeed()}
function polishSiteFeed(){document.body.dataset.page=view.type;const empty=$('feed')?.querySelector('.empty');if(empty&&!['graph','gallery','relations'].includes(view.type)&&!empty.querySelector('[data-site-compose]')){const b=document.createElement('button');b.type='button';b.className='primary siteEmptyAction';b.dataset.siteCompose='true';b.textContent='写一篇新帖';empty.append(b)}document.querySelector('main')?.setAttribute('aria-label','观星塔内容');document.querySelector('aside')?.setAttribute('aria-label','导航与档案')}
const sitePolishRender=render;render=function(){sitePolishRender();if(ready)polishSiteShell()};
const sitePolishFeed=renderFeed;renderFeed=function(){sitePolishFeed();polishSiteFeed()};
window.addEventListener('DOMContentLoaded',()=>{if(ready)polishSiteShell()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.siteCompose)$('newPost').click();if(b.dataset.view&&e.composedPath().includes(document.querySelector('aside'))&&matchMedia('(max-width:760px)').matches){document.querySelector('aside').classList.remove('siteMobileOpen');$('siteMobileNavigation')?.setAttribute('aria-expanded','false');document.querySelector('main').scrollIntoView({block:'start',behavior:'smooth'})}});
